import {planJourney,places,scenarios,formatTime} from './engine.js';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const defaults={origin:'tampines',destination:'raffles',departure:'07:40',deadline:'08:45',scenario:'disruption',comfort:false,threshold:10,large:false};
let state={...defaults};try{const saved=JSON.parse(localStorage.getItem('margin-routine')||'null');if(saved)state={...state,...saved};planJourney(state);}catch{state={...defaults};}
let plan,selected,zoom=1,stepIndex=0,toastTimer;const modal=$('#modal');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('margin-routine',JSON.stringify(state));}catch{toast('Storage unavailable. Your routine will last for this session.');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3500);}
function showModal(title,html,eyebrow='A LITTLE MORE CONTEXT'){ $('#modal-content').innerHTML=`<h2>${title}</h2>${html}`;$('#modal-eyebrow').textContent=eyebrow;if(!modal.open)modal.showModal();}
function currentRoute(){return plan.routes.find(r=>r.id===selected)||plan.best;}
function fillForm(){for(const key of ['origin','destination','deadline','departure','threshold'])$('#'+key).value=state[key];$('#comfort').checked=state.comfort;$('#large-text').checked=state.large;document.body.classList.toggle('large-text',state.large);}
function render(reset=true){plan=planJourney(state);if(reset)selected=plan.best.id;const route=currentRoute();const recommended=plan.best;$('#scenario-label').textContent='REPLAY';$('#decision-title').textContent=recommended.buffer<0?'Let’s rethink your departure.':recommended.id==='usual'?'Your usual way looks good.':'Take the Downtown Line today.';$('#decision-copy').textContent=recommended.buffer<0?`Even the best option arrives after ${state.deadline}. Leave by ${formatTime(plan.latestLeave)} to make it on time.`:plan.event.delay?`The East–West Line is running ${plan.event.delay} minutes slower. ${recommended.id==='usual'?'Your routine still gives you enough breathing room.':'A small switch keeps your morning on track.'}`:state.scenario==='rain'?'A wet morning adds uncertainty. We’ve allowed extra walking time in your arrival range.':'You’ve got time on your side. We’ll keep quiet unless something puts your arrival at risk.';
 $('#buffer').textContent=Math.abs(recommended.buffer);$('#buffer-unit').textContent=recommended.buffer<0?'min after your deadline':'min to breathe';$('#buffer-ring span').textContent=recommended.buffer<0?'!':'✓';$('#arrival-summary').textContent=`Arrive ${formatTime(plan.start+recommended.min)}–${formatTime(recommended.arrival)}`;$('#quiet-copy').textContent=plan.interrupted?'This change crosses your alert threshold. A heads-up is useful.':`Your ${plan.usual.buffer}-minute buffer is safe. No notification needed.`;
 $('#route-list').innerHTML=[...plan.routes].sort((a,b)=>(a.id===recommended.id?-1:b.id===recommended.id?1:0)).map(r=>`<button class="route-card ${r.id===selected?'selected':''}" data-route="${r.id}" aria-pressed="${r.id===selected}"><div class="route-top"><span class="route-name"><span class="radio"></span>${r.name}</span><span class="route-duration">${r.min}–${r.max} <small>min</small></span></div><div class="route-chain"><span class="walk">Walk</span><span>›</span>${r.lines.map(l=>l==='walk'?'<span class="walk">Walk</span>':`<span class="line-badge ${l.toLowerCase()}">${l}</span>`).join('<span>›</span>')}<span>›</span><span class="walk">Walk</span>${r.id===recommended.id?'<span class="recommend-tag">BEST FOR YOU</span>':''}</div><div class="route-meta"><span class="crowd"><span class="crowd-bars ${r.crowd}"><i></i><i></i><i></i></span>${{low:'Room to breathe',medium:'Some standing',high:'Likely crowded'}[r.crowd]}</span><span class="${r.delay?'delay-tag':''}">${r.delay?`+${r.delay} min delay`:`${r.walk} min walking`} · ${formatTime(r.arrival)}</span></div></button>`).join('');
 $('#network-title').textContent=plan.event.delay?'EWL · Slower this morning':'EWL · Normal service';$('#network-copy').textContent=plan.event.delay?`${state.scenario==='planned'?'Planned works':'Replay signal fault'} · +${plan.event.delay} min`:'Replay conditions · no major delays';$('#weather-title').textContent=plan.event.rain?'A little rain ahead':'A brighter start';$('#weather-copy').textContent=plan.event.rain?'Replay weather · bring an umbrella':'Replay weather · dry walking legs';$('#leave-label').textContent=`LEAVE AT ${state.departure}`;$('#step-preview').innerHTML=route.steps.slice(0,2).map((s,i)=>stepHtml(s,i)).join('');drawMap();renderMobileSummary();}
function stepHtml(s,i){return `<div class="step-row"><span class="step-number">${i+1}</span><div><strong>${s.title}</strong><p>${s.detail}</p></div><span>${s.minutes} min</span></div>`;}
function project([lon,lat]){return [(lon-103.829)/.132*900,(1.366-lat)/.092*610];}
function path(points){return points.map((p,i)=>`${i?'L':'M'}${project(p).map(v=>v.toFixed(1)).join(',')}`).join(' ');}
function drawMap(){if(!plan)return;const route=currentRoute(),usual=plan.usual;let html=`<path d="${path(usual.geometry)}" fill="none" stroke="#749782" stroke-width="4" stroke-dasharray="7 7" stroke-linejoin="round"/>`;if(plan.event.delay)html+=`<path d="${path([[103.8923,1.3178],[103.8829,1.3115],[103.8714,1.3074]])}" fill="none" stroke="#c9715a" stroke-width="7" stroke-linecap="round" stroke-dasharray="4 3"/>`;html+=`<path d="${path(route.geometry)}" fill="none" stroke="white" stroke-width="9" stroke-linejoin="round" stroke-linecap="round"/><path d="${path(route.geometry)}" fill="none" stroke="#4d7bd3" stroke-width="4.5" stroke-linejoin="round" stroke-linecap="round"/>`;if(route.id==='usual'&&plan.event.delay)html+=`<path d="${path([[103.8923,1.3178],[103.8829,1.3115],[103.8714,1.3074]])}" fill="none" stroke="#c9715a" stroke-width="6" stroke-linecap="round"/>`;
 route.geometry.filter((_,i)=>i%3===0).forEach(p=>{const[x,y]=project(p);html+=`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="#4d7bd3" stroke-width="2"/>`;});$('#map-routes').innerHTML=html;
 const labels=[['TAMPINES',[103.939,1.361]],['BEDOK',[103.927,1.331]],['PAYA LEBAR',[103.894,1.313]],['GEYLANG',[103.880,1.300]],['KALLANG',[103.865,1.319]],['MARINA BAY',[103.866,1.281]],['DOWNTOWN',[103.842,1.276]]];let labelHtml=labels.map(([n,c])=>{const[x,y]=project(c);return `<text x="${x}" y="${y}" text-anchor="middle" font-family="system-ui" font-size="10" letter-spacing="2" fill="#9aa58f">${n}</text>`;}).join('');
 for(const [key,name] of [[state.origin,'Home'],[state.destination,'Destination']]){const[x,y]=project(places[key].coord);labelHtml+=`<circle cx="${x}" cy="${y}" r="11" fill="${key===state.origin?'#fff':'#193e35'}" stroke="${key===state.origin?'#4d7bd3':'#fff'}" stroke-width="3"/><circle cx="${x}" cy="${y}" r="3" fill="${key===state.origin?'#4d7bd3':'#dff1b0'}"/><rect x="${Math.min(x-64,745)}" y="${y-44}" width="128" height="25" rx="5" fill="white" filter="url(#shadow)"/><text x="${Math.min(x,809)}" y="${y-27}" text-anchor="middle" fill="#294b40" font-size="11" font-family="system-ui" font-weight="600">${places[key].station}</text>`;}
 if(plan.event.delay){const[x,y]=project([103.891,1.3015]);labelHtml+=`<rect x="${x-63}" y="${y}" width="126" height="29" rx="5" fill="#fffaf3" stroke="#e1b69e"/><text x="${x}" y="${y+19}" text-anchor="middle" font-size="11" font-family="system-ui" fill="#af654c">! EWL +${plan.event.delay} min</text>`;}$('#map-labels').innerHTML=labelHtml;}
async function loadMap(){try{const r=await fetch('/data/osm-roads.json');if(!r.ok)throw Error();const data=await r.json();$('#geography').innerHTML=data.elements.filter(e=>e.geometry).map(e=>`<path d="${path(e.geometry.map(p=>[p.lon,p.lat]))}" fill="none" stroke="${e.tags.highway==='motorway'?'#d4ddc9':'#fff'}" stroke-width="${e.tags.highway==='motorway'?5:2.2}" opacity=".95" stroke-linecap="round"/>`).join('');}catch{$('#geography').innerHTML='<text x="30" y="580" fill="#7c8872" font-size="12">Map base unavailable · route diagram only</text>';}}
$('#journey-form').addEventListener('submit',e=>{e.preventDefault();state.origin=$('#origin').value;state.destination=$('#destination').value;state.deadline=$('#deadline').value;save();render();$('.journey-editor').open=false;toast('Your routes have been rebalanced.');});
$('#route-list').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b){selected=b.dataset.route;render(false);}});
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
function switchView(view){for(const key of ['journey','week','settings'])$('#'+key+'-view').classList.toggle('hidden',key!==view);$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='week')renderWeek();document.body.dataset.screen=view;window.scrollTo({top:0,behavior:'instant'});}
$('#close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
$('#scenario-open').onclick=()=>{showModal('Every morning is different.',Object.entries(scenarios).map(([key,s],i)=>`<button class="scenario-option" data-scenario="${key}"><span>${['↯','☀','◷','☂','▦'][i]}</span><div><strong>${s.name}</strong><p>${s.description}</p></div></button>`).join(''),'TRY A MORNING · SYNTHETIC REPLAYS');};
$('#modal-content').addEventListener('click',e=>{const b=e.target.closest('[data-scenario]');if(b){state.scenario=b.dataset.scenario;save();render();switchView('journey');modal.close();toast(`${scenarios[state.scenario].name} replay loaded`);}if(e.target.closest('#next-step')){stepIndex++;showJourney();}if(e.target.closest('#end-trip')){try{localStorage.removeItem('margin-active-trip');}catch{}modal.close();toast('Journey complete. You’ve got this.');}if(e.target.closest('#refresh-weather'))refreshWeather();});
$('#why-button').onclick=()=>{const r=plan.best;showModal('A little buffer changes everything.',`<p>We rank the available journeys using the slower end of their estimated arrival range, then account for crowding and your preferences.</p><div class="explanation-row"><span>Your arrival deadline</span><strong>${state.deadline}</strong></div><div class="explanation-row"><span>Usual route, cautious arrival</span><strong>${formatTime(plan.usual.arrival)}</strong></div><div class="explanation-row"><span>Recommended, cautious arrival</span><strong>${formatTime(r.arrival)}</strong></div><div class="explanation-row"><span>Your remaining buffer</span><strong>${r.buffer} minutes</strong></div><p>${plan.notice} Alerts trigger below your ${state.threshold}-minute buffer threshold. We keep your usual route when it is safe and within five minutes of the best option.</p><span class="source-label">RULE-BASED ESTIMATE · NOT A PROBABILITY</span>`);};
$('#quiet-settings').onclick=()=>switchView('settings');
$('#settings-form').onsubmit=e=>{e.preventDefault();state.departure=$('#departure').value;state.threshold=Number($('#threshold').value);state.comfort=$('#comfort').checked;state.large=$('#large-text').checked;save();fillForm();render();toast('Routine saved on this device.');};
$('#clear-data').onclick=()=>{try{localStorage.removeItem('margin-routine');localStorage.removeItem('margin-active-trip');}catch{}state={...defaults};fillForm();render();toast('Your saved routine and trip have been cleared.');};
$('#network-info').onclick=()=>showModal('What changed on your route?',`<span class="source-label">${plan.event.label}</span><p>${plan.event.description}</p><p>${plan.event.delay?'The affected segment is Paya Lebar → Aljunied → Kallang. The Downtown Line alternative avoids this segment; joining the EWL at Bugis is outside it.':'No major incident is active in this replay.'}</p><p>This demo does not connect to LTA’s live service-alert feed. No free shuttle or bus boarding is assumed.</p>`);
$('#weather-info').onclick=()=>showModal('Check the sky before you go.',`<p>The journey currently uses <strong>${plan.event.rain?'rainy':'dry'} replay conditions</strong>. You can separately check the latest public forecast for Tampines.</p><button class="primary-button" id="refresh-weather">Fetch current NEA forecast ↗</button><div id="weather-result"></div>`,'WEATHER · SOURCE CHECK');
async function refreshWeather(){const b=$('#refresh-weather'),out=$('#weather-result');b.disabled=true;out.innerHTML='<p>Checking data.gov.sg…</p>';try{const r=await fetch('https://api-open.data.gov.sg/v2/real-time/api/two-hr-forecast',{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const data=await r.json();const item=data.data?.items?.[0];const forecast=item?.forecasts?.find(x=>x.area==='Tampines');if(!forecast)throw Error();out.innerHTML=`<span class="source-label">LIVE FETCH · NEA VIA DATA.GOV.SG</span><p><strong>Tampines: ${escape(forecast.forecast)}</strong><br>Issued: ${escape(item.timestamp)}<br>Valid: ${escape(item.valid_period?.start)} to ${escape(item.valid_period?.end)}</p><p>Shown separately from the replay so current weather is never mixed silently with synthetic transport data.</p>`;}catch{out.innerHTML='<p>Current weather is unavailable. The labelled replay remains available; no live forecast has been assumed.</p>';}finally{b.disabled=false;}}
function renderWeek(){$('#week-content').innerHTML='<article class="week-card"><span class="source-label">TOMORROW · SYNTHETIC PLANNED EVENT</span><h3>EWL frequency reduced, 07:00–09:00</h3><p>Your morning trip overlaps this work window. Plan a Downtown Line alternative today and avoid a last-minute decision on the platform.</p><button class="primary-button" id="preview-planned">Plan around these works <span>↗</span></button></article><article class="week-card"><h3>Your day-before check</h3><p>We compare the planned window with your saved departure time and route. In this demo, the check runs when you open this view; background push notifications are not enabled.</p></article>';$('#preview-planned').onclick=()=>{state.scenario='planned';save();render();switchView('journey');toast('Tomorrow’s planned-works replay loaded.');};}
$('#start-journey').onclick=()=>{stepIndex=0;try{localStorage.setItem('margin-active-trip',JSON.stringify({route:currentRoute(),savedAt:new Date().toISOString(),scenario:state.scenario}));}catch{}showJourney();};
function showJourney(){const r=currentRoute();if(stepIndex>=r.steps.length){showModal('A little breathing room. You’re here.',`<p>You’ve reached ${places[state.destination].name}. This walkthrough used illustrative timings and manually advanced steps.</p><button class="primary-button" id="end-trip">Finish journey ✓</button>`,'JOURNEY WALKTHROUGH');return;}const s=r.steps[stepIndex];showModal(s.title,`<div class="journey-progress"><div style="width:${(stepIndex+1)/r.steps.length*100}%"></div></div><p>${s.detail}</p><div class="explanation-row"><span>Estimated leg duration</span><strong>${s.minutes} minutes</strong></div><div class="explanation-row"><span>Journey estimate</span><strong>${formatTime(plan.start+r.min)}–${formatTime(r.arrival)}</strong></div><p>Saved on this device for the journey. ${navigator.onLine?'Replay conditions, not live navigation.':'Offline: conditions may have changed.'}</p><button class="primary-button" id="next-step">${stepIndex===r.steps.length-1?'I’ve arrived':'Done · next step'} →</button>`,`STEP ${stepIndex+1} OF ${r.steps.length} · DEMO WALKTHROUGH`);}
$('#sources-button').onclick=()=>showModal('Clear about what we know.',`<span class="source-label">HACKATHON PROTOTYPE · RACHEL’S COMMUTE</span><p><strong>Map:</strong> a bundled OpenStreetMap road extract, under ODbL. Route overlays join reference station coordinates; they are illustrative and are not pedestrian turn-by-turn routing.</p><p><strong>Routes:</strong> curated rail alternatives for three origins and three destinations. Travel ranges, crowd levels, and disruptions are synthetic estimates, not calibrated predictions or current LTA data. Walks are included but shelter, exits and accessibility are not verified.</p><p><strong>Weather:</strong> the optional live check calls NEA via data.gov.sg with its issue and validity times; it does not overwrite demo conditions.</p><p><strong>Privacy:</strong> your routine and active journey remain in this browser’s local storage until reset. There is no server account or location tracking. Offline app caching works after the first successful visit in a compatible browser.</p><p><a href="https://github.com/aochinwen/NebulaX-Hackathon-ProblemStatement/blob/main/PS2/PS2_README.md" target="_blank" rel="noopener">Problem statement 2 ↗</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap licence ↗</a></p>`,'DATA & TRANSPARENCY');
function setZoom(value){zoom=Math.max(1,Math.min(2.5,value));const w=900/zoom,h=610/zoom;$('#route-map').setAttribute('viewBox',`${(900-w)/2} ${(610-h)/2} ${w} ${h}`);}$('#zoom-in').onclick=()=>setZoom(zoom+.25);$('#zoom-out').onclick=()=>setZoom(zoom-.25);$('#map-reset').onclick=()=>setZoom(1);
function connection(){$('#offline-banner').classList.toggle('hidden',navigator.onLine);}window.addEventListener('online',connection);window.addEventListener('offline',connection);
function renderMobileSummary(){const r=currentRoute();$('#commute-summary').textContent=`${places[state.origin].station} → ${places[state.destination].station}`;$('#commute-time').textContent=`Leave ${state.departure} · arrive by ${state.deadline}`;$('#selected-arrival').textContent=`Arrive ${formatTime(r.arrival)}`;$('#selected-name').textContent=r.name;}
function showMap(show){document.body.dataset.map=String(show);$('#show-plan').setAttribute('aria-pressed',String(!show));$('#show-map').setAttribute('aria-pressed',String(show));}
$('#show-plan').onclick=()=>showMap(false);$('#show-map').onclick=()=>showMap(true);$('#mobile-start').onclick=()=>$('#start-journey').click();
let installPrompt=null;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
$('#install-app').onclick=async()=>{if(installPrompt){await installPrompt.prompt();const result=await installPrompt.userChoice;installPrompt=null;if(result.outcome==='accepted')toast('Margin has been added to your home screen.');return;}showModal('Your commute, one tap away.','<p><strong>iPhone:</strong> open Margin in Safari, tap Share, then choose Add to Home Screen.</p><p><strong>Android:</strong> open Margin in Chrome, open the menu, then choose Install app or Add to Home screen.</p><p>Use the published HTTPS link on your phone. Margin opens as a standalone web app where your browser supports it.</p>','ADD TO HOME SCREEN');};
fillForm();render();loadMap();connection();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_commute_replay',title:'Configure commute replay',description:'Set a supported demo corridor and replay scenario, recompute routes, and save the routine on this device. Does not fetch live transport data.',inputSchema:{type:'object',properties:{origin:{type:'string',enum:['tampines','bedok','paya']},destination:{type:'string',enum:['raffles','bugis','chinatown']},scenario:{type:'string',enum:Object.keys(scenarios)}},required:['origin','destination','scenario'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!['origin','destination','scenario'].includes(k))||!['tampines','bedok','paya'].includes(input.origin)||!['raffles','bugis','chinatown'].includes(input.destination)||!Object.hasOwn(scenarios,input.scenario))throw new Error('Invalid supported corridor or replay scenario.');const next={...state,...input};planJourney(next);state=next;save();fillForm();render();switchView('journey');return {scenario:state.scenario,recommendedRoute:plan.best.id,arrival:formatTime(plan.best.arrival),bufferMinutes:plan.best.buffer,dataMode:'synthetic transport replay'};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
